#!/usr/bin/env python3
"""M16: backend-readiness evidence for the persistent D3D12 engine.

Three independent paths are compared:

  * canonical reference - the historical M15-C hashes, generated by the
    accepted `m_b6_frame.py` path with only the encoder colour changing;
  * live reference - `m_b6_frame.py` with the frame colour supplied to post and
    downsample as well (`--colour` + `--image-colour`);
  * persistent engine - one process, four caller-created input textures and one
    caller-owned output texture per frame.

The live references for frames 0..11 are generated fresh.  Canonical references
are reused from the M15-C evidence when present, otherwise regenerated.  The
script also drives the caller-owned command list, external-device, cancellation
and negative-conformance paths, then measures the production workload.

  m16_readiness.py --out DIR [--manifest engine.txt] [--reuse] [--references N]
"""
import argparse
import hashlib
import json
import os
import shutil
import statistics
import subprocess
import sys
from pathlib import Path

import numpy as np

HERE = Path(__file__).resolve().parent
REPO = HERE.parent
sys.path.insert(0, str(HERE))
TEMP = Path(os.environ.get('LOCALAPPDATA', os.path.expanduser('~'))) / 'Temp/opencode'
DEFAULT_LAYERS = TEMP / 'm09h-complete-chain-20261030/layers'
DEFAULT_FIXTURES = Path(os.environ.get('SETTE_FIXTURES', TEMP / 'm-capture-run/fixtures'))
M15C_EVIDENCE = TEMP / 'evidence-20261031-m15c'

import m10_temporal as temporal  # noqa: E402
import m15c_compose as composer  # noqa: E402

ACCEPTED_FRAME = 'f76ac032f45a91dc6c4ead22979eff16ed1d04c4a4cf1add2ff1adc0bd4d6c00'
ACCEPTED_CHAIN = 'c89208ed744acd71275f349d99d758c16bd55c77a6fb5d3da88109a3573c6b0d'
M15C_BASELINE = {
    'gpu_ms_median': 172.215,
    'init_ms': 1173.19,
    'record_ms_median': 1.100,
    'arena_heap_bytes': 450625536,
    'peak_transient_bytes': 376579856,
    'dxgi_after_execute': 833900544,
}


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def run(command, allow_fail=False):
    done = subprocess.run([str(c) for c in command], capture_output=True, text=True)
    if done.returncode and not allow_fail:
        raise RuntimeError('command failed:\n' + ' '.join(map(str, command)) +
                           '\n' + done.stdout[-2000:] + '\n' + done.stderr[-2000:])
    return done


def motion_variant(index):
    """Deterministic RG16F motion bytes.  The reset path binds but never reads
    this texture; using a different buffer per frame proves no stale descriptor
    and that the unread input cannot perturb the output."""
    h, w = temporal.H, temporal.W
    y, x = np.mgrid[0:h, 0:w]
    data = np.empty((h, w, 2), np.float16)
    data[..., 0] = ((x * 3 + y * 5 + index * 7) % 31 - 15) / 256.0
    data[..., 1] = ((x * 5 + y * 3 + index * 11) % 29 - 14) / 256.0
    return data


def write_frames(path, frames):
    Path(path).write_text(json.dumps(frames, indent=2), encoding='utf-8')


def reference_frame(out, colour, image_colour, layers):
    """Run the accepted standalone harness for one input combination."""
    out = Path(out)
    command = [sys.executable, HERE / 'm_b6_frame.py', '--out', out, '--no-repeat',
               '--colour', colour,
               '--enc0-mode', 'int8-embedding', '--attention-mode', 'int8',
               '--cumulative-mode', 'spatial', '--cumulative-layers', layers,
               '--fuse-mlp', '--network-arena', '--network-mode', 'production']
    if image_colour is not None:
        command += ['--image-colour', image_colour]
    run(command, allow_fail=True)
    frame_file = out / 'downsample-native' / 'results' / 'out-out.bin'
    if not frame_file.is_file():
        raise SystemExit(f'reference was not produced: {out}')
    report_file = out / 'b6.json'
    if report_file.is_file():
        execution = json.loads(report_file.read_text()).get('execution', {})
        if execution.get('status') == 'FAIL':
            raise SystemExit(f'reference execution FAIL: {execution.get("reasons")}')
    return sha(frame_file)


def engine_run(engine, manifest, shaders, frames_file, out, mode='validation',
               dump_frame=0, recover=False, caller=False, caller_readback=None,
               external_device=False, debug=False, extra=()):
    out = Path(out)
    command = [engine, '--manifest', manifest, '--shaders', shaders,
               '--output', 'frame_out', '--frames-file', frames_file,
               '--mode', mode, '--report', out / 'report.json']
    if mode == 'validation':
        command += ['--dump-dir', out / 'dumps', '--dump-frame', str(dump_frame)]
    if recover:
        command.append('--recover')
    if caller:
        command.append('--caller-list')
    if caller_readback:
        command += ['--caller-readback', caller_readback]
    if external_device:
        command.append('--external-device')
    if debug:
        command.append('--debug')
    command += list(extra)
    run(command)
    return json.loads((out / 'report.json').read_text())


def dump_hash(root, subdir, name='out-frame.bin'):
    return sha(Path(root) / 'dumps' / subdir / name)


def compare_hashes(dumps, references, count):
    matches = {}
    for index in range(count):
        got = dump_hash(dumps, f'frame-{index:02d}')
        matches[str(index)] = {'engine': got, 'reference': references[str(index)],
                               'match': got == references[str(index)]}
    return matches


def main():
    ap = argparse.ArgumentParser(description=__doc__,
                                 formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument('--out', type=Path, required=True)
    ap.add_argument('--manifest', type=Path, help='existing composed engine.txt')
    ap.add_argument('--layers', type=Path, default=DEFAULT_LAYERS)
    ap.add_argument('--fixtures', type=Path, default=DEFAULT_FIXTURES)
    ap.add_argument('--engine', type=Path,
                    default=REPO / 'build/native/Release/m_inference_stage.exe')
    ap.add_argument('--shaders', type=Path, default=REPO / 'build/native')
    ap.add_argument('--canonical-references', type=Path,
                    default=M15C_EVIDENCE / 'references.json')
    ap.add_argument('--reuse', action='store_true')
    ap.add_argument('--skip-live-references', action='store_true')
    a = ap.parse_args()
    if a.out.exists():
        if not a.reuse:
            raise SystemExit(f'{a.out} exists; use a fresh directory')
    else:
        a.out.mkdir(parents=True)

    temporal.FIXTURES = a.fixtures
    colour = temporal.load_colour()
    inputs = a.out / 'inputs'
    inputs.mkdir(exist_ok=True)
    frames = []
    for index, (name, description) in enumerate(temporal.SCENARIOS):
        frame = temporal.variant(colour, name)
        frame_path = inputs / f'frame-{index:02d}.bin'
        motion_path = inputs / f'motion-{index:02d}.bin'
        if not frame_path.exists():
            frame_path.write_bytes(frame.tobytes())
        if not motion_path.exists():
            motion_path.write_bytes(motion_variant(index).tobytes())
        frames.append({'index': index, 'scenario': name, 'description': description,
                       'colour': frame_path, 'motion': motion_path,
                       'colour_sha256': sha(frame_path),
                       'motion_sha256': sha(motion_path)})
    count = len(frames)

    if a.manifest:
        manifest = a.manifest
    else:
        composed = a.out / 'compose'
        if a.reuse and (composed / 'engine.txt').is_file():
            manifest = composed / 'engine.txt'
        else:
            composer.compose(composed, a.layers, a.fixtures, fused=True)
            manifest = composed / 'engine.txt'

    canonical_colour = a.fixtures / 'post' / 'in-colour.bin'
    canonical_motion = a.fixtures / 'post' / 'in-motion.bin'
    canonical_down = a.fixtures / 'downsample' / 'in-colour.bin'

    # -------------------------------------------------------------- references
    canonical = {}
    if a.canonical_references and Path(a.canonical_references).is_file():
        hashes = json.loads(Path(a.canonical_references).read_text())['hashes']
        canonical = {str(k): v for k, v in hashes.items()}
        print(f'canonical references: {a.canonical_references}', flush=True)
    else:
        for frame in frames:
            target = a.out / 'reference-canonical' / f'frame-{frame["index"]:02d}'
            canonical[str(frame['index'])] = reference_frame(
                target, frame['colour'], None, a.layers)
            shutil.rmtree(target)
            print(f'canonical reference {frame["index"]:02d}', flush=True)

    live_file = a.out / 'references-live.json'
    live = {}
    if live_file.is_file():
        live = json.loads(live_file.read_text())['hashes']
    elif not a.skip_live_references:
        for frame in frames:
            target = a.out / 'reference-live' / f'frame-{frame["index"]:02d}'
            live[str(frame['index'])] = reference_frame(
                target, frame['colour'], frame['colour'], a.layers)
            shutil.rmtree(target)
            print(f'live reference {frame["index"]:02d} {live[str(frame["index"])][:16]}',
                  flush=True)
        live_file.write_text(json.dumps({'hashes': live}, indent=2))
    if len(canonical) != count:
        raise SystemExit('canonical references are incomplete')
    if canonical['0'] != ACCEPTED_FRAME:
        raise SystemExit(f'canonical frame 0 {canonical["0"]} is not the accepted frame')
    if len(live) != count:
        raise SystemExit('live references are missing; rerun without --skip-live-references')

    # ------------------------------------------------------ canonical engine run
    canonical_frames = []
    for frame in frames:
        canonical_frames.append({
            'enc0_in_colour': str(frame['colour']),
            'post_colour': str(canonical_colour),
            'post_motion': str(canonical_motion),
            'down_colour': str(canonical_down),
        })
    canonical_frames_file = a.out / 'frames-canonical.json'
    write_frames(canonical_frames_file, canonical_frames)
    canonical_out = a.out / 'engine-canonical'
    canonical_report = engine_run(
        a.engine, manifest, a.shaders, canonical_frames_file, canonical_out,
        mode='validation', dump_frame=0, recover=True, debug=True)
    canonical_matches = compare_hashes(canonical_out, canonical, count)
    canonical_recovery = dump_hash(canonical_out, 'recover')
    print('canonical engine: %d/%d' % (
        sum(v['match'] for v in canonical_matches.values()), count), flush=True)

    # ----------------------------------------------------------- live engine run
    live_frames = []
    for frame in frames:
        live_frames.append({
            'enc0_in_colour': str(frame['colour']),
            'post_colour': str(frame['colour']),
            'post_motion': str(frame['motion']),
            'down_colour': str(frame['colour']),
        })
    live_frames_file = a.out / 'frames-live.json'
    write_frames(live_frames_file, live_frames)
    live_out = a.out / 'engine-live'
    live_report = engine_run(
        a.engine, manifest, a.shaders, live_frames_file, live_out,
        mode='validation', dump_frame=0, recover=True, debug=True)
    live_matches = compare_hashes(live_out, live, count)
    live_recovery = dump_hash(live_out, 'recover')
    print('live engine: %d/%d' % (sum(v['match'] for v in live_matches.values()), count),
          flush=True)

    # -------------------------------------------------------- borrowed-list paths
    caller_out = a.out / 'caller-list'
    caller_report = engine_run(
        a.engine, manifest, a.shaders, canonical_frames_file, caller_out,
        mode='production', caller=True, caller_readback=caller_out / 'frame.bin',
        debug=True, extra=('--frames', '1'))
    caller_hash = sha(caller_out / 'frame.bin')

    external_out = a.out / 'external-device'
    external_report = engine_run(
        a.engine, manifest, a.shaders, canonical_frames_file, external_out,
        mode='production', caller=True, caller_readback=external_out / 'frame.bin',
        external_device=True, debug=True, extra=('--frames', '1'))
    external_hash = sha(external_out / 'frame.bin')

    borrowed_out = a.out / 'borrowed-sequence'
    borrowed_report = engine_run(
        a.engine, manifest, a.shaders, canonical_frames_file, borrowed_out,
        mode='production', caller=True, debug=True)
    borrowed_ok = all(not row['engine_submitted'] and not row['engine_waited']
                      for row in borrowed_report['runs'])

    cancel_out = a.out / 'caller-cancel'
    cancel_report = engine_run(
        a.engine, manifest, a.shaders, canonical_frames_file, cancel_out,
        mode='production', caller=True, debug=True,
        extra=('--caller-cancel', '--frames', '1'))
    cancel_ok = (not cancel_report['runs'][0]['engine_submitted'] and
                 not cancel_report['runs'][0]['engine_waited'])

    # ---------------------------------------------------------- negative selftest
    selftest = a.out / 'external-selftest'
    selftest.mkdir(exist_ok=True)
    selftest_command = [a.engine, '--manifest', manifest, '--shaders', a.shaders,
                        '--output', 'frame_out', '--external-selftest', selftest,
                        '--report', selftest / 'report.json', '--debug']
    for entry in canonical_frames[0].items():
        selftest_command += ['--input', f'{entry[0]}={entry[1]}']
    run(selftest_command)
    selftest_report = json.loads((selftest / 'external-selftest.json').read_text())

    # -------------------------------------------------------------- measurement
    # A one-frame process holds exactly one input set, so its DXGI sample is
    # the engine's resident footprint rather than a sequence preload.
    one_frame_file = a.out / 'frames-one.json'
    write_frames(one_frame_file, canonical_frames[:1])
    warm = a.out / 'warm'
    warm_report = engine_run(a.engine, manifest, a.shaders, one_frame_file, warm,
                             mode='production')
    steady = a.out / 'steady'
    steady_report = engine_run(a.engine, manifest, a.shaders, canonical_frames_file,
                               steady, mode='production')
    gpu = [row['gpu_ms'] for row in steady_report['runs']]
    record = [row['record_ms'] for row in steady_report['runs']]
    wait = [row['submit_wait_ms'] for row in steady_report['runs']]
    benchmark = {
        'init_ms': steady_report['init']['total_ms'],
        'init': steady_report['init'],
        'memory': steady_report['memory'],
        'dxgi': steady_report['dxgi'],
        'frames': len(gpu),
        'gpu_ms_median': statistics.median(gpu),
        'gpu_ms_min': min(gpu),
        'gpu_ms_max': max(gpu),
        'record_ms_median': statistics.median(record),
        'submit_wait_ms_median': statistics.median(wait),
        'per_frame_gpu_ms': gpu,
        'dispatches': steady_report['runs'][0]['dispatches'],
        'copies': steady_report['runs'][0]['copies'],
        'transitions': steady_report['runs'][0]['transitions'],
        'uav_barriers': steady_report['runs'][0]['uav_barriers'],
        'aliasing_barriers': steady_report['runs'][0]['aliasing_barriers'],
        'external_rebinds': steady_report['runs'][0]['external_rebinds'],
        'm15c_baseline': M15C_BASELINE,
        'delta_gpu_ms': statistics.median(gpu) - M15C_BASELINE['gpu_ms_median'],
        'delta_init_ms': steady_report['init']['total_ms'] - M15C_BASELINE['init_ms'],
        'delta_peak_transient_bytes': (steady_report['memory']['peak_transient_bytes'] -
                                       M15C_BASELINE['peak_transient_bytes']),
        'one_frame': {'memory': warm_report['memory'], 'dxgi': warm_report['dxgi'],
                      'gpu_ms': warm_report['runs'][0]['gpu_ms'],
                      'record_ms': warm_report['runs'][0]['record_ms']},
        'delta_one_frame_dxgi': (warm_report['dxgi']['after_execute_usage'] -
                                 M15C_BASELINE['dxgi_after_execute']),
        'delta_one_frame_committed_bytes': (
            warm_report['memory']['committed_bytes'] -
            92897408),
    }

    checks = {
        'canonical_frame0_accepted': canonical_matches['0']['engine'] == ACCEPTED_FRAME,
        'canonical_all_frames': all(v['match'] for v in canonical_matches.values()),
        'canonical_recovery': canonical_recovery == canonical['0'],
        'live_all_frames': all(v['match'] for v in live_matches.values()),
        'live_recovery': live_recovery == live['0'],
        'caller_list_exact': caller_hash == ACCEPTED_FRAME,
        'external_device_exact': external_hash == ACCEPTED_FRAME,
        'borrowed_never_submits': borrowed_ok,
        'cancellation_safe': cancel_ok,
        'external_selftest': selftest_report.get('status') == 'PASS',
        'canonical_zero_debug': canonical_report['debug']['errors'] == 0,
        'live_zero_debug': live_report['debug']['errors'] == 0,
        'caller_zero_debug': caller_report['debug']['errors'] == 0,
        'external_device_zero_debug': external_report['debug']['errors'] == 0,
        'allocation_inventory_unchanged': (
            warm_report['memory']['committed_allocations'] ==
            steady_report['memory']['committed_allocations'] and
            warm_report['memory']['placed_allocations'] ==
            steady_report['memory']['placed_allocations'] and
            warm_report['memory']['committed_bytes'] ==
            steady_report['memory']['committed_bytes'] and
            warm_report['memory']['arena_heap_bytes'] ==
            steady_report['memory']['arena_heap_bytes']),
        'no_production_readbacks': all(row['readback_ms'] == 0
                                       for row in steady_report['runs']),
    }
    status = 'PASS' if all(checks.values()) else 'FAIL'
    report = {
        'status': status,
        'manifest': str(manifest),
        'accepted_frame': ACCEPTED_FRAME,
        'accepted_chain': ACCEPTED_CHAIN,
        'frames': [{'index': f['index'], 'scenario': f['scenario'],
                    'colour_sha256': f['colour_sha256'],
                    'motion_sha256': f['motion_sha256']} for f in frames],
        'canonical': {'matches': canonical_matches,
                      'recovery': canonical_recovery,
                      'report': canonical_report},
        'live': {'matches': live_matches,
                 'recovery': live_recovery,
                 'report': live_report},
        'caller_list': {'sha256': caller_hash, 'report': caller_report},
        'external_device': {'sha256': external_hash, 'report': external_report},
        'borrowed_sequence': {'all_not_submitted': borrowed_ok,
                              'report': borrowed_report},
        'cancellation': {'safe': cancel_ok, 'report': cancel_report},
        'external_selftest': selftest_report,
        'benchmark': benchmark,
        'checks': checks,
    }
    (a.out / 'readiness.json').write_text(json.dumps(report, indent=2))
    print(json.dumps({'status': status, 'checks': checks,
                      'canonical': sum(v['match'] for v in canonical_matches.values()),
                      'live': sum(v['match'] for v in live_matches.values()),
                      'gpu_ms_median': benchmark['gpu_ms_median'],
                      'init_ms': benchmark['init_ms'],
                      'caller': caller_hash == ACCEPTED_FRAME,
                      'external_device': external_hash == ACCEPTED_FRAME,
                      'selftest': selftest_report.get('status')}, indent=2))
    return 0 if status == 'PASS' else 1


if __name__ == '__main__':
    raise SystemExit(main())
